package com.mendes.scheduling_platform.security;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {try{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){Claims c=jwt.parse(h.substring(7));boolean platform=Boolean.TRUE.equals(c.get("platform",Boolean.class));Long tenant=c.get("tenantId",Long.class);String authority=platform?"ROLE_PLATFORM_ADMIN":"ROLE_"+c.get("role",String.class);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(c.getSubject(),null,List.of(new SimpleGrantedAuthority(authority))));if(!platform)TenantContext.set(tenant);}chain.doFilter(req,res);}catch(JwtException e){res.sendError(401,"Token inválido ou expirado");}finally{TenantContext.clear();}}}
